import{_ as a,c as t,o as r,ae as s}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Feature tour","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1795170900000}'),o={name:"guide/features.md"};function d(i,e,n,l,h,u){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="feature-tour" tabindex="-1">Feature tour <a class="header-anchor" href="#feature-tour" aria-label="Permalink to &quot;Feature tour&quot;">​</a></h1><p>A short guide to the things you&#39;ll use most.</p><h2 id="everyday-browsing" tabindex="-1">Everyday browsing <a class="header-anchor" href="#everyday-browsing" aria-label="Permalink to &quot;Everyday browsing&quot;">​</a></h2><ul><li>Multiple tabs and windows: drag them out, group them, fold a group away, mute a tab or hover to preview.</li><li>The address bar suggests sites you know first, then falls back to search.</li><li>Command palette (⌘K), tab search (⌘⇧A), find on page (⌘F) and a keyboard shortcut list in the gear menu.</li></ul><h2 id="easy-on-the-eyes" tabindex="-1">Easy on the eyes <a class="header-anchor" href="#easy-on-the-eyes" aria-label="Permalink to &quot;Easy on the eyes&quot;">​</a></h2><ul><li>Appearance: follow system, light or dark. You can also force dark pages and switch themes automatically each day.</li><li>Six accent colours: blue, violet, teal, green, orange and rose.</li><li>Bookmark bar: always hidden, always visible, or only on the new tab page.</li></ul><h2 id="ads-and-scripts" tabindex="-1">Ads and scripts <a class="header-anchor" href="#ads-and-scripts" aria-label="Permalink to &quot;Ads and scripts&quot;">​</a></h2><ul><li>Ad blocking supports subscriptions, your own rules and a whitelist. If a subscription fails to update, the old rules keep working.</li><li>User scripts (<code>.user.js</code>) are managed in Settings and install as soon as the download finishes.</li></ul><h2 id="videos-and-files" tabindex="-1">Videos and files <a class="header-anchor" href="#videos-and-files" aria-label="Permalink to &quot;Videos and files&quot;">​</a></h2><ul><li>Downloads can pause, resume, cancel and retry. When a download finishes you can reveal it in Finder or open it with the related app.</li><li>The media panel detects videos on a page and saves them as one MP4, even when the site serves them in pieces.</li></ul><h2 id="shortcuts-at-a-glance" tabindex="-1">Shortcuts at a glance <a class="header-anchor" href="#shortcuts-at-a-glance" aria-label="Permalink to &quot;Shortcuts at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>⌘T / ⌘W</td><td>New / close tab</td></tr><tr><td>⌘L</td><td>Focus the address bar</td></tr><tr><td>⌘F</td><td>Find on the page</td></tr><tr><td>⌘⇧N</td><td>Private window</td></tr><tr><td>⌘K</td><td>Command palette</td></tr><tr><td>⌘⇧A</td><td>Search tabs</td></tr><tr><td>⌘⇧R</td><td>Reading mode</td></tr></tbody></table>',12)])])}const b=a(o,[["render",d]]);export{p as __pageData,b as default};
